		"no created": `{"id":"e","type":"x"}`,
	} {
		t.Run(name, func(t *testing.T) {
			st := &memStore{events: map[string]Event{}}
			if rec := post(t, st, b, sign(testSecret, fixedNow.Unix(), b)); rec.Code != 400 {
				t.Fatalf("code %d, want 400", rec.Code)
			}
		})
	}
}

